const services={service:{title:'Keep your car\nrunning well.',type:'ROUTINE SERVICE',description:'Keep everyday wear in check with the servicing your car needs — based on its age, mileage and condition.',items:['Oil and filter changes','Fluid and safety checks','A clear summary of findings'],label:'Request a service',value:'Routine service'},diagnostics:{title:'Find the fault.\nPlan the fix.',type:'DIAGNOSTICS',description:'A new sound, a warning light or a change in performance? Start with a focused inspection and understand what’s behind it.',items:['Electronic fault investigation','Checks based on your symptoms','Findings explained before repairs'],label:'Request diagnostics',value:'Diagnostics'},brakes:{title:'Confidence in\nevery stop.',type:'BRAKES & SUSPENSION',description:'Changes in braking, vibration or steering deserve a closer look. We inspect the connected parts before recommending work.',items:['Brake discs, pads and fluid','Suspension and steering checks','A vehicle-specific scope of work'],label:'Request a brake check',value:'Brakes & suspension'}};
const tabs=[...document.querySelectorAll('[data-service]')];
function selectService(key,focus=false){const s=services[key];tabs.forEach(t=>{const active=t.dataset.service===key;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;if(active&&focus)t.focus();});document.querySelector('#service-panel').setAttribute('aria-labelledby',`tab-${key}`);document.querySelector('.service-panel__type').textContent=s.type;document.querySelector('#service-title').textContent=s.title;document.querySelector('#service-description').textContent=s.description;document.querySelector('#service-items').replaceChildren(...s.items.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));document.querySelector('#service-request').firstChild.textContent=s.label+' ';document.querySelector('select[name="service"]').value=s.value;}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectService(tab.dataset.service));tab.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tabs.length)%tabs.length;selectService(tabs[next].dataset.service,true);});});
document.querySelectorAll('[data-pick-service]').forEach(link=>link.addEventListener('click',()=>selectService(link.dataset.pickService)));
let summary='';document.querySelector('#request-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);summary=`Service request\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nVehicle: ${data.get('vehicle')}\nService: ${data.get('service')}\n\n${data.get('message')}`;document.querySelector('#request-summary').textContent=summary;document.querySelector('#copy-status').textContent='';const result=document.querySelector('#request-result');result.hidden=false;result.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
document.querySelector('#copy-request').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summary);document.querySelector('#copy-status').textContent='Request copied.';}catch{document.querySelector('#copy-status').textContent='Select the summary above to copy it.';}});
import('../shared/product-scene.js').then(({mountProducts})=>mountProducts('brake')).catch(()=>{});
import('../shared/editorial-motion.js').then(({revealSections})=>revealSections('.section-heading, .principles article, .faq h2, .booking>div')).catch(()=>{});
